const fs = require('fs');

const meta = JSON.parse(fs.readFileSync('/tmp/opencode/views.json', 'utf8'));
const bin = fs.readFileSync('/tmp/opencode/views.bin');
const W = meta[0].w, H = meta[0].h, WH = W * H;

function buildCameras(fovyDeg, azSign) {
  const f = (H / 2) / Math.tan((fovyDeg * Math.PI / 180) / 2);
  return meta.map((m, idx) => {
    const az = azSign * m.az * Math.PI / 180;
    const el = m.el * Math.PI / 180;
    const fx = Math.cos(az) * Math.cos(el);
    const fy = Math.sin(az) * Math.cos(el);
    const fz = Math.sin(el);
    // right = normalize(cross(f, [0,0,1])) = [fy, -fx, 0] / hypot(fx, fy)
    const rh = Math.hypot(fx, fy);
    const rx = fy / rh, ry = -fx / rh, rz = 0;
    // up = cross(right, f)
    const ux = ry * fz - rz * fy;
    const uy = rz * fx - rx * fz;
    const uz = rx * fy - ry * fx;
    const cx = m.lookat[0] - m.dist * fx;
    const cy = m.lookat[1] - m.dist * fy;
    const cz = m.lookat[2] - m.dist * fz;
    return { fx, fy, fz, rx, ry, rz, ux, uy, uz, cx, cy, cz, f, offset: idx * WH };
  });
}

// Dilate foreground by 1px to tolerate subpixel/antialiasing when testing coarse voxels
const dilated = new Uint8Array(bin.length);
for (let v = 0; v < meta.length; v++) {
  const off = v * WH;
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      let mask = 0;
      for (let dy = -1; dy <= 1; dy++) {
        const ny = y + dy;
        if (ny < 0 || ny >= H) continue;
        for (let dx = -1; dx <= 1; dx++) {
          const nx = x + dx;
          if (nx < 0 || nx >= W) continue;
          const c = bin[off + ny * W + nx];
          if (c === 1) mask |= 1;
          else if (c === 2) mask |= 2;
        }
      }
      dilated[off + y * W + x] = mask;
    }
  }
}

for (const azSign of [1, -1]) {
  for (const fovy of [30, 35, 40, 45, 50, 55, 60]) {
    const cams = buildCameras(fovy, azSign);
    let fgCount = 0;
    for (let x = -0.6; x <= 3.0; x += 0.08) {
      for (let y = -0.6; y <= 2.6; y += 0.08) {
        for (let z = -0.8; z <= 1.6; z += 0.08) {
          let misses = 0;
          for (let i = 0; i < cams.length; i++) {
            const c = cams[i];
            const dx = x - c.cx, dy = y - c.cy, dz = z - c.cz;
            const depth = dx * c.fx + dy * c.fy + dz * c.fz;
            if (depth <= 0.1) { misses = 99; break; }
            const u = Math.round((W - 1) / 2 + c.f * (dx * c.rx + dy * c.ry + dz * c.rz) / depth);
            const vp = Math.round((H - 1) / 2 - c.f * (dx * c.ux + dy * c.uy + dz * c.uz) / depth);
            if (u < 0 || u >= W || vp < 0 || vp >= H) continue;
            if (dilated[c.offset + vp * W + u] === 0) {
              if (++misses > 0) break;
            }
          }
          if (misses === 0) fgCount++;
        }
      }
    }
    console.log(`azSign=${azSign} fovy=${fovy}: fgVoxels(8cm)=${fgCount}`);
  }
}
