const fs = require('fs');

const meta = JSON.parse(fs.readFileSync('/tmp/opencode/views.json', 'utf8'));
const bin = fs.readFileSync('/tmp/opencode/views.bin');
const W = meta[0].w, H = meta[0].h, WH = W * H;

function buildCameras(fovyDeg) {
  const f = (H / 2) / Math.tan((fovyDeg * Math.PI / 180) / 2);
  return meta.map((m, idx) => {
    const az = m.az * Math.PI / 180;
    const el = m.el * Math.PI / 180;
    const fx = Math.cos(az) * Math.cos(el);
    const fy = Math.sin(az) * Math.cos(el);
    const fz = Math.sin(el);
    const rh = Math.hypot(fx, fy);
    const rx = fy / rh, ry = -fx / rh, rz = 0;
    const ux = ry * fz - rz * fy;
    const uy = rz * fx - rx * fz;
    const uz = rx * fy - ry * fx;
    const cx = m.lookat[0] - m.dist * fx;
    const cy = m.lookat[1] - m.dist * fy;
    const cz = m.lookat[2] - m.dist * fz;
    return { fx, fy, fz, rx, ry, rz, ux, uy, uz, cx, cy, cz, f, offset: idx * WH };
  });
}

// Distance transform (max distance to any foreground pixel) for fast hierarchical culling
const distBg = new Float32Array(bin.length);
for (let v = 0; v < meta.length; v++) {
  const off = v * WH;
  const INF = 1e4;
  for (let i = 0; i < WH; i++) distBg[off + i] = bin[off + i] > 0 ? 0 : INF;
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const idx = off + y * W + x;
      let d = distBg[idx];
      if (x > 0) d = Math.min(d, distBg[idx - 1] + 1);
      if (y > 0) d = Math.min(d, distBg[idx - W] + 1);
      distBg[idx] = d;
    }
  }
  for (let y = H - 1; y >= 0; y--) {
    for (let x = W - 1; x >= 0; x--) {
      const idx = off + y * W + x;
      let d = distBg[idx];
      if (x + 1 < W) d = Math.min(d, distBg[idx + 1] + 1);
      if (y + 1 < H) d = Math.min(d, distBg[idx + W] + 1);
      distBg[idx] = d;
    }
  }
}

function carveAtFovy(fovy, minSize = 0.01) {
  const cams = buildCameras(fovy);
  const voxA = [], voxB = [];

  function recurse(cx, cy, cz, half) {
    const r3d = half * 1.7320508;
    let inViews = 0;
    let greyVotes = 0, blueVotes = 0;
    for (let i = 0; i < cams.length; i++) {
      const c = cams[i];
      const dx = cx - c.cx, dy = cy - c.cy, dz = cz - c.cz;
      const depth = dx * c.fx + dy * c.fy + dz * c.fz;
      if (depth <= 0.2) return;
      const u = (W - 1) / 2 + c.f * (dx * c.rx + dy * c.ry + dz * c.rz) / depth;
      const vp = (H - 1) / 2 - c.f * (dx * c.ux + dy * c.uy + dz * c.uz) / depth;
      const radPx = c.f * r3d / Math.max(0.2, depth - r3d) + 0.75;
      const ui = Math.round(u), vi = Math.round(vp);
      if (ui < 0 || ui >= W || vi < 0 || vi >= H) continue;
      inViews++;
      const d = distBg[c.offset + vi * W + ui];
      if (d > radPx) return; // Guaranteed outside silhouette in view i!
      if (half <= minSize / 2 + 1e-9) {
        // Check 3x3 neighborhood at leaf for color votes
        let has1 = false, has2 = false;
        for (let yy = Math.max(0, vi - 1); yy <= Math.min(H - 1, vi + 1); yy++) {
          for (let xx = Math.max(0, ui - 1); xx <= Math.min(W - 1, ui + 1); xx++) {
            const cls = bin[c.offset + yy * W + xx];
            if (cls === 1) has1 = true;
            else if (cls === 2) has2 = true;
          }
        }
        if (has1 && !has2) greyVotes++;
        else if (has2 && !has1) blueVotes++;
        else if (has1 && has2) { greyVotes += 0.5; blueVotes += 0.5; }
      }
    }
    if (inViews < 20) return;
    if (half <= minSize / 2 + 1e-9) {
      // Remember occlusion: a voxel of A can be occluded by B in a FEW views (looking blue),
      // and vice versa, so majority vote across ~76 views cleanly separates A from B!
      if (blueVotes > greyVotes) voxB.push([cx, cy, cz, blueVotes / inViews]);
      else voxA.push([cx, cy, cz, greyVotes / inViews]);
      return;
    }
    const h2 = half / 2;
    for (let sx = -1; sx <= 1; sx += 2)
      for (let sy = -1; sy <= 1; sy += 2)
        for (let sz = -1; sz <= 1; sz += 2)
          recurse(cx + sx * h2, cy + sy * h2, cz + sz * h2, h2);
  }

  recurse(1.0, 0.6, 0.2, 2.56); // 5.12m cube -> subdivides by 2 down to 0.01m (2.56 / 256 = 0.01)!
  return { voxA, voxB };
}

for (const fovy of [35, 40, 42, 44, 45, 46, 48, 50]) {
  const { voxA, voxB } = carveAtFovy(fovy, 0.02);
  let maxR = 0;
  for (const p of voxB) {
    const r = Math.hypot(p[0] - 1.2, p[1] - 0.36, p[2] - 0.28);
    if (r > maxR) maxR = r;
  }
  let minD = 1e9;
  for (let i = 0; i < voxA.length; i += 2) {
    const a = voxA[i];
    for (let j = 0; j < voxB.length; j += 2) {
      const b = voxB[j];
      const d = Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);
      if (d < minD) minD = d;
    }
  }
  console.log(`fovy=${fovy}: voxA=${voxA.length} voxB=${voxB.length} maxR_B=${maxR.toFixed(4)} (gt 1.5839) minD=${minD.toFixed(4)} (gt 0.0445)`);
}
