const fs = require('fs');

const meta = JSON.parse(fs.readFileSync('/tmp/opencode/views.json', 'utf8'));
const bin = fs.readFileSync('/tmp/opencode/views.bin');
const W = meta[0].w, H = meta[0].h, WH = W * H;

// Exact 2D Euclidean distance transform to non-bg, to grey(1), and to blue(2)
function edt2d(maskFn) {
  const out = new Float32Array(bin.length);
  const INF = 1e6;
  const f = new Float32Array(Math.max(W, H));
  const d = new Float32Array(Math.max(W, H));
  const v = new Int32Array(Math.max(W, H));
  const z = new Float32Array(Math.max(W, H) + 1);

  function edt1d(n) {
    let k = 0;
    v[0] = 0; z[0] = -INF; z[1] = INF;
    for (let q = 1; q < n; q++) {
      let s = ((f[q] + q * q) - (f[v[k]] + v[k] * v[k])) / (2 * q - 2 * v[k]);
      while (s <= z[k]) {
        k--;
        s = ((f[q] + q * q) - (f[v[k]] + v[k] * v[k])) / (2 * q - 2 * v[k]);
      }
      k++; v[k] = q; z[k] = s; z[k + 1] = INF;
    }
    k = 0;
    for (let q = 0; q < n; q++) {
      while (z[k + 1] < q) k++;
      const dx = q - v[k];
      d[q] = dx * dx + f[v[k]];
    }
  }

  for (let view = 0; view < meta.length; view++) {
    const off = view * WH;
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) f[x] = maskFn(bin[off + y * W + x]) ? 0 : INF;
      edt1d(W);
      for (let x = 0; x < W; x++) out[off + y * W + x] = d[x];
    }
    for (let x = 0; x < W; x++) {
      for (let y = 0; y < H; y++) f[y] = out[off + y * W + x];
      edt1d(H);
      for (let y = 0; y < H; y++) out[off + y * W + x] = Math.sqrt(d[y]);
    }
  }
  return out;
}

const distAny = edt2d(c => c > 0);

function buildCameras(fovyDeg) {
  const f = (H / 2) / Math.tan((fovyDeg * Math.PI / 180) / 2);
  return meta.map((m, idx) => {
    const az = m.az * Math.PI / 180;
    const el = m.el * Math.PI / 180;
    const fx = Math.cos(az) * Math.cos(el);
    const fy = Math.sin(az) * Math.cos(el);
    const fz = Math.sin(el);
    const rh = Math.hypot(fx, fy);
    const rx = fy / rh, ry = -fx / rh, rz = 0;
    const ux = ry * fz - rz * fy;
    const uy = rz * fx - rx * fz;
    const uz = rx * fy - ry * fx;
    const cx = m.lookat[0] - m.dist * fx;
    const cy = m.lookat[1] - m.dist * fy;
    const cz = m.lookat[2] - m.dist * fz;
    return { fx, fy, fz, rx, ry, rz, ux, uy, uz, cx, cy, cz, f, offset: idx * WH };
  });
}

function carveExact(fovy, minSize = 0.01) {
  const cams = buildCameras(fovy);
  const candidates = [];

  function recurse(cx, cy, cz, half) {
    const r3d = half * 1.7320508;
    let inViews = 0;
    for (let i = 0; i < cams.length; i++) {
      const c = cams[i];
      const dx = cx - c.cx, dy = cy - c.cy, dz = cz - c.cz;
      const depth = dx * c.fx + dy * c.fy + dz * c.fz;
      if (depth <= 0.2) return;
      // OpenGL pixel centers are at (0.5, 0.5), so center of WxH viewport is W/2 - 0.5 = (W-1)/2
      const u = (W - 1) / 2 + c.f * (dx * c.rx + dy * c.ry + dz * c.rz) / depth;
      const vp = (H - 1) / 2 - c.f * (dx * c.ux + dy * c.uy + dz * c.uz) / depth;
      const ui = Math.round(u), vi = Math.round(vp);
      if (ui < 0 || ui >= W || vi < 0 || vi >= H) continue;
      inViews++;
      const radPx = c.f * r3d / Math.max(0.2, depth - r3d) + 0.6;
      if (distAny[c.offset + vi * W + ui] > radPx) return;
    }
    if (inViews < 25) return;
    if (half <= minSize / 2 + 1e-9) {
      candidates.push([cx, cy, cz]);
      return;
    }
    const h2 = half / 2;
    for (let sx = -1; sx <= 1; sx += 2)
      for (let sy = -1; sy <= 1; sy += 2)
        for (let sz = -1; sz <= 1; sz += 2)
          recurse(cx + sx * h2, cy + sy * h2, cz + sz * h2, h2);
  }
  recurse(1.0, 0.6, 0.2, 2.56);

  // Now perform z-buffer occlusion-aware photo-consistency across all 76 views!
